 function readFile(file){return new Promise(function(resolve,reject){var reader=new FileReader();reader.onload=function(){resolve(String(reader.result).split(',')[1]);};reader.onerror=function(){reject(new Error('文件读取失败，请重新选择'));};reader.readAsDataURL(file);});}
 async function upload(files){if(busy)return;await act(async function(){if(!workspace||!account)throw new Error('请先登录，再添加私人材料。');var epoch=identityEpoch,owner=account,subject=id('upload-subject').value,count=0,duplicates=0,errors=[];for(var i=0;i<files.length;i++){accountGuard(epoch,owner);var f=files[i];id('upload-status').hidden=false;id('upload-status').textContent='正在保存 '+(i+1)+' / '+files.length+' 份原件：'+f.name;if(f.size>10*1024*1024){errors.push(f.name+' 超过10MB');continue;}if(['image/jpeg','image/png','application/pdf'].indexOf(f.type)<0){errors.push(f.name+' 不是JPG、PNG或PDF');continue;}try{var base64=await readFile(f);accountGuard(epoch,owner);var r=await api('/materials',{name:f.name,subject:subject,mime:f.type,base64:base64});accountGuard(epoch,owner);selected.add(r.material.id);if(r.duplicate)duplicates++;else count++;}catch(e){accountGuard(epoch,owner);errors.push(e.message);}}accountGuard(epoch,owner);await refresh();accountGuard(epoch,owner);id('file-input').value='';notice('已保存 '+count+' 份原件'+(duplicates?'，'+duplicates+' 份重复材料已保留原件':'')+'。可以继续添加，选好后点击生成学习报告。'+(errors.length?'\n'+errors.join('；'):''),errors.length?'info':'success');});id('upload-status').hidden=true;id('upload-status').textContent='';}
 function confirmAnalysis(kind,selection,maximum){return new Promise(function(resolve){var epoch=identityEpoch,owner=account,dialog=node('dialog','report-action-confirm'),settled=false;var title=node('h2','',kind==='extract'?'仅识别这批材料':kind==='analyze'?'分析已核对的题':'开始生成学习报告');title.id='analysis-confirm-title';dialog.setAttribute('aria-labelledby',title.id);dialog.appendChild(node('p','eyebrow','由你决定何时开始'));dialog.appendChild(title);var price=node('strong','confirm-price',maximum);price.appendChild(node('small','','ANS积分上限'));dialog.appendChild(price);dialog.appendChild(node('p','',kind==='extract'?'只识别，不生成综合报告。':kind==='analyze'?'包含逐题诊断和一次综合，不重新识别原件。':'包含原件识别、逐题方法诊断和综合建议。实际题数识别后才能确定。'));var list=node('div','confirm-selection');selection.forEach(function(item){var row=kind==='analyze'?workspace.questions.find(function(q){return q.id===item.id;}):workspace.materials.find(function(m){return m.id===item.id;});list.appendChild(node('div','',kind==='analyze'?labels[row.subject]+' · '+row.record.module+' · 第'+row.record.questionNo+'题':row.name));});dialog.appendChild(list);dialog.appendChild(node('p','scope-note','逐阶段预留，成功后按实际处理结算，不超过此上限。失败或取消按任务回执退回预留积分；网络不确定时显示“结算待核对”。'));dialog.appendChild(node('p','scope-note','材料仅发送至你已同意的当前AI渠道。上传和下载不额外调用模型。'));var actions=node('div','confirm-actions');function finish(ok){if(settled)return;settled=true;window.removeEventListener('wrongbook:account',onAccount);dialog.close();dialog.remove();try{accountGuard(epoch,owner);}catch(e){resolve(false);return;}resolve(ok);}function onAccount(){finish(false);}actions.appendChild(btn('再看看','secondary',function(){finish(false);}));actions.appendChild(btn('确认开始分析 →','primary',function(){finish(true);}));dialog.appendChild(actions);dialog.addEventListener('cancel',function(e){e.preventDefault();finish(false);});dialog.addEventListener('click',function(e){if(e.target===dialog){var r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)finish(false);}});window.addEventListener('wrongbook:account',onAccount);document.body.appendChild(dialog);dialog.showModal();actions.firstChild.focus();});}
 async function begin(kind){await act(async function(){if(!id('ai-consent').checked)throw Error('请先同意本次所选材料由AI渠道处理。');var epoch=identityEpoch,owner=account,selection=kind!=='analyze'?workspace.materials.filter(function(m){return selected.has(m.id);}).map(function(m){return {id:m.id,version:m.version};}):workspace.questions.filter(function(q){return picked.has(q.id)&&q.confirmed;}).map(function(q){return {id:q.id,version:q.version};});if(!selection.length)throw Error('先选中需要处理的材料或题目。');var version=workspace.ai.pricingVersion;if(version!=='stage-points-v1')throw Error('积分确认规则正在更新，请刷新后再开始。');var max=kind==='extract'?selection.length:kind==='analyze'?Math.ceil(selection.length/4)+1:selection.length+Math.ceil(Math.min(100,selection.length*40)/4)+1;if(!await confirmAnalysis(kind,selection,max))return;accountGuard(epoch,owner);var body={confirmed:true,key:uid(),maxPoints:max,pricingVersion:version};body[kind!=='analyze'?'materials':'questions']=selection;var r=await api('/'+kind,body);lastJob=r.job.id;window.dispatchEvent(new CustomEvent('exam-analysis:companion',{detail:{phase:'running',runId:lastJob}}));await refresh();var settled=workspace.jobs.find(function(j){return j.id===lastJob;});if(settled&&settled.status==='succeeded'){location.hash=kind==='extract'?'questions':'report';notice(settled.message);return;}notice(kind==='extract'?'识别已开始，完成后核对题目。':'Agent 已开始分析，完成后可打开报告；旧报告会保留。');});}
 async function download(route,name){var blob=await binary(route,'导出未完成，请稍后重试。'),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},30000);notice('已开始下载「'+name+'」，请在浏览器下载列表查看。');}
 async function flush(){if(!account)return;var owner=account;var outbox=saved('outbox',[]),remaining=[];for(var i=0;i<outbox.length;i++){try{await api('/questions/'+outbox[i].id+'/review',outbox[i].body);}catch(e){remaining.push(outbox[i]);}}if(account!==owner)return;save('outbox',remaining);if(outbox.length)notice(remaining.length?'有 '+remaining.length+' 条离线复练记录未同步；题目可能已更新，请核对后处理。':'离线复练记录已同步到此账号。');}
 id('question-search').addEventListener('input',function(e){if(busy)return;questionQuery=e.target.value;questionPage=0;renderQuestions();buttons();});
 document.querySelectorAll('[data-question-filter]').forEach(function(n){n.addEventListener('click',function(){if(busy)return;questionFilter=n.dataset.questionFilter;questionPage=0;renderQuestions();buttons();});});
