 id('question-pick-page').addEventListener('click',function(){if(busy||!workspace)return;var added=0;pageQuestions().forEach(function(q){if(q.confirmed&&!picked.has(q.id)&&picked.size<12){picked.add(q.id);added++;}});renderQuestionList(visibleQuestions());buttons();notice('本页新选 '+added+' 道，合计 '+picked.size+' 道。尚未开始分析。');});
 id('question-clear-picked').addEventListener('click',function(){if(busy)return;picked.clear();renderQuestionList(visibleQuestions());buttons();});
 id('choose-file').addEventListener('click',function(){id('file-input').click();});id('file-input').addEventListener('change',function(e){upload(Array.from(e.target.files));});var drop=id('drop-zone');drop.addEventListener('dragover',function(e){e.preventDefault();drop.classList.add('dragging');});drop.addEventListener('dragleave',function(){drop.classList.remove('dragging');});drop.addEventListener('drop',function(e){e.preventDefault();drop.classList.remove('dragging');upload(Array.from(e.dataTransfer.files));});id('ai-consent').addEventListener('change',buttons);id('question-ai-consent').addEventListener('change',function(){id('ai-consent').checked=id('question-ai-consent').checked;buttons();});id('study-button').addEventListener('click',function(){begin('study');});id('extract-button').addEventListener('click',function(){begin('extract');});id('analyze-button').addEventListener('click',function(){begin('analyze');});id('record-report').addEventListener('click',function(){act(async function(){var selection=workspace.questions.filter(function(q){return picked.has(q.id)&&q.confirmed;}).map(function(q){return {id:q.id,version:q.version};});await api('/report',{confirmed:true,questions:selection});await refresh();location.hash='report';notice('已根据你确认的题目生成记录报告，没有发起模型调用。');});});id('manual-question').addEventListener('click',function(){manual();});id('material-search').addEventListener('input',function(e){query=e.target.value;renderMaterials();buttons();});document.querySelectorAll('[data-filter]').forEach(function(n){n.addEventListener('click',function(){filter=n.dataset.filter;document.querySelectorAll('[data-filter]').forEach(function(b){b.setAttribute('aria-pressed',String(b===n));});renderMaterials();buttons();});});id('select-all').addEventListener('click',function(){if(!workspace)return;var visible=visibleMaterials(),all=visible.length>0&&visible.every(function(m){return selected.has(m.id);});visible.forEach(function(m){if(all)selected.delete(m.id);else selected.add(m.id);});renderMaterials();buttons();});id('clear-selection').addEventListener('click',function(){selected.clear();renderMaterials();buttons();});id('review-minutes').addEventListener('change',renderReview);id('export-archive').addEventListener('click',function(){act(async function(){await download('/archive','私人错题档案.json');});});id('reload-workspace').addEventListener('click',function(){act(refresh);});var printDetails=[];window.addEventListener('beforeprint',function(){if(!workspace||!workspace.report)return;document.body.dataset.printReport='true';printDetails=Array.from(document.querySelectorAll('#report-content details')).map(function(n){var state={node:n,open:n.open};n.open=true;return state;});});window.addEventListener('afterprint',function(){printDetails.forEach(function(x){x.node.open=x.open;});printDetails=[];delete document.body.dataset.printReport;});window.addEventListener('hashchange',render);window.addEventListener('online',function(){act(async function(){await refresh();await flush();await refresh();});});window.addEventListener('wrongbook:account',function(e){if(!e.detail.user){gate('ANS登录已退出或到期，请重新登录。');}else if(!workspace){if(busy)pendingRefresh=true;else act(refresh);}});
 setInterval(async function(){if(window.ANSPlatformShell)return;if(!account||offline||busy)return;try{var res=await fetch('/api/auth/session',{cache:'no-store',credentials:'same-origin'});if(res.ok){var data=await res.json();if(!data.user)gate('ANS登录已到期。重新登录后材料仍在。');else{var digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('wrongbook-v1|'+data.user.id));var idNow=Array.from(new Uint8Array(digest),function(v){return v.toString(16).padStart(2,'0');}).join('');if(idNow!==account)gate('账号已切换，请重新打开当前账号错题本。');}}}catch(e){}},60000);
